mapper.select:
SELECT 
FROM business_role


     and role_code=#{roleCode}


        and id != #{notRole,jdbcType=BIGINT}

mapper.delete:
delete from bus_user_role
where user_id = #{userId,jdbcType=BIGINT}

    and role_id in (SELECT id FROM business_role WHERE role_code=#{roleCode})

mapper.select:
select a.id,a.role_name as roleName,a.role_desc as roleDesc,(case when r.id is null then 0 else 1 end) as selected from business_role a

  left join bus_apply_product_role r on a.id = r.role_id and r.product_id = #{leftId,jdbcType=BIGINT}


  left join bus_apply_org_role r on a.id = r.role_id and r.org_id = #{leftId,jdbcType=BIGINT}


  left join bus_apply_corporation_role r on a.id = r.role_id and r.corporation_id = #{leftId,jdbcType=BIGINT}


  left join bus_apply_enum_role r on a.id = r.role_id and r.enum_id = #{leftId,jdbcType=BIGINT}


  left join bus_apply_item_role r on a.id = r.role_id and r.item_id = #{leftId,jdbcType=BIGINT}

where 1 = 1

  and a.role_name  like  CONCAT(CONCAT('%',#{roleName,jdbcType=VARCHAR}), '%')

order by a.id asc
